    31	    public Javalin create() {
    32	        ObjectMapper mapper = new ObjectMapper()
    33	                .registerModule(new JavaTimeModule())
    34	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    35	        Javalin app = Javalin.create(config -> config.jsonMapper(new JavalinJackson(mapper, false)));
    36	
    37	        app.get("/rooms", ctx -> ctx.json(reservations.rooms()));
    38	        app.post("/reservations", ctx -> ctx.status(201).json(reservations.create(reader.read(ctx.body()))));
    39	        app.get("/reservations/{id}", ctx -> ctx.json(reservations.get(id(ctx))));
    40	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(reservations.confirm(id(ctx))));
    41	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(reservations.cancel(id(ctx))));
    42	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(reservations.checkIn(id(ctx))));
    43	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(reservations.checkOut(id(ctx))));
    44	        app.get("/reservations/{id}/document", ctx -> ctx.json(reservations.receipt(id(ctx))));
    45	        app.get("/messages", ctx -> ctx.json(reservations.sentMessages()));
    46	        app.get("/reports/occupancy", ctx -> ctx.contentType(CSV).result(reports.occupancy(dateParam(ctx, "date"))));
    47	        app.get("/reports/revenue", ctx -> ctx.contentType(CSV).result(reports.revenue(monthParam(ctx, "month"))));
    48	
    49	        app.exception(ServiceException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    50	        app.exception(Exception.class, (e, ctx) -> {
    51	            e.printStackTrace();
    52	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    53	        });
    54	        return app;
    55	    }
