     1	package br.com.marealta.pousada.web;
     2	
     3	import br.com.marealta.pousada.domain.RatePlan;
     4	import br.com.marealta.pousada.service.NewReservation;
     5	import br.com.marealta.pousada.service.ServiceException;
     6	import com.fasterxml.jackson.core.JsonProcessingException;
     7	import com.fasterxml.jackson.databind.JsonNode;
     8	import com.fasterxml.jackson.databind.ObjectMapper;
     9	
    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeParseException;
    12	
    13	/** Lê o corpo do POST /reservations, recusando com INVALID_REQUEST o que estiver faltando ou mal formado. */
    14	class ReservationRequestReader {
    15	
    16	    private final ObjectMapper mapper = new ObjectMapper();
    17	
    18	    NewReservation read(String body) {
    19	        JsonNode json;
    20	        try {
    21	            json = mapper.readTree(body);
    22	        } catch (JsonProcessingException e) {
    23	            throw ServiceException.invalid("O corpo não é um JSON válido");
    24	        }
    25	        if (json == null || !json.isObject()) {
    26	            throw ServiceException.invalid("O corpo deve ser um objeto JSON");
    27	        }
    28	        return new NewReservation(
    29	                integer(json, "roomNumber"),
    30	                text(json, "guestName"),
    31	                text(json, "guestEmail"),
    32	                text(json, "guestCpf"),
    33	                date(json, "checkIn"),
    34	                date(json, "checkOut"),
    35	                integer(json, "guests"),
    36	                ratePlan(json));
    37	    }
    38	
    39	    private static String text(JsonNode json, String field) {
    40	        JsonNode node = json.get(field);
    41	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    42	            throw ServiceException.invalid("Campo " + field + " ausente ou inválido");
    43	        }
    44	        return node.asText();
    45	    }
    46	
    47	    private static int integer(JsonNode json, String field) {
    48	        JsonNode node = json.get(field);
    49	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    50	            throw ServiceException.invalid("Campo " + field + " ausente ou inválido");
    51	        }
    52	        return node.asInt();
    53	    }
    54	
    55	    private static LocalDate date(JsonNode json, String field) {
    56	        try {
    57	            return LocalDate.parse(text(json, field));
    58	        } catch (DateTimeParseException e) {
    59	            throw ServiceException.invalid("Campo " + field + " deve estar no formato AAAA-MM-DD");
    60	        }
    61	    }
    62	
    63	    private static RatePlan ratePlan(JsonNode json) {
    64	        try {
    65	            return RatePlan.valueOf(text(json, "ratePlan"));
    66	        } catch (IllegalArgumentException e) {
    67	            throw ServiceException.invalid("Campo ratePlan deve ser STANDARD ou NON_REFUNDABLE");
    68	        }
    69	    }
    70	}
