    21	    public ReportService(Database database, ReservationRepository reservations) {
    22	        this.database = database;
    23	        this.reservations = reservations;
    24	    }
    25	
    26	    public String occupancy(LocalDate night) {
    27	        List<Reservation> occupying = query(c -> reservations.findPaidOccupying(c, night));
    28	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    29	        for (Reservation r : occupying) {
    30	            Room room = RoomCatalog.find(r.roomNumber()).orElseThrow();
    31	            csv.append(room.number()).append(',').append(room.type()).append(',').append(r.id()).append(',')
    32	                    .append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    33	        }
    34	        long occupiedRooms = occupying.stream().map(Reservation::roomNumber).distinct().count();
    35	        csv.append("total,").append(occupiedRooms).append('/').append(RoomCatalog.all().size()).append('\n');
    36	        return csv.toString();
    37	    }
    38	
    39	    public String revenue(YearMonth month) {
    40	        List<Reservation> starting = query(c ->
    41	                reservations.findStartingBetween(c, month.atDay(1), month.plusMonths(1).atDay(1)));
    42	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    43	        BigDecimal total = Money.ZERO;
    44	        for (Reservation r : starting) {
    45	            BigDecimal retained = r.retained();
    46	            if (retained.signum() <= 0) {
    47	                continue;
    48	            }
    49	            csv.append(r.id()).append(',').append(r.roomNumber()).append(',').append(r.checkIn()).append(',')
    50	                    .append(r.checkOut()).append(',').append(r.status()).append(',')
    51	                    .append(retained.toPlainString()).append('\n');
    52	            total = total.add(retained);
    53	        }
    54	        csv.append("total,").append(total.toPlainString()).append('\n');
    55	        return csv.toString();
    56	    }
    57	
    58	    private <T> T query(Database.Work<T> work) {
    59	        try {
    60	            return database.inTransaction(work);
    61	        } catch (SQLException e) {
    62	            throw new IllegalStateException("Erro no banco de dados", e);
    63	        }
    64	    }
    65	}
