    20	public class ReservationService {
    21	
    22	    /** Uma mudança de situação: o novo estado da reserva e as mensagens que ela provoca. */
    23	    private record Outcome(Reservation reservation, List<Message> messages) {
    24	    }
    25	
    26	    private interface Change {
    27	        Outcome apply(Reservation current, Room room);
    28	    }
    29	
    30	    private final Database database;
    31	    private final ReservationRepository reservations;
    32	    private final MessageRepository messages;
    33	    private final ReservationEvents events;
    34	
    35	    public ReservationService(Database database, ReservationRepository reservations, MessageRepository messages,
    36	                              ReservationEvents events) {
    37	        this.database = database;
    38	        this.reservations = reservations;
    39	        this.messages = messages;
    40	        this.events = events;
    41	    }
    42	
    43	    public List<Room> rooms() {
    44	        return RoomCatalog.all();
    45	    }
    46	
    47	    public Reservation create(NewReservation request) {
    48	        Room room = RoomCatalog.find(request.roomNumber()).orElseThrow(
    49	                () -> new ServiceException(404, "ROOM_NOT_FOUND", "Quarto " + request.roomNumber() + " não existe"));
    50	        if (request.guests() > room.capacity()) {
    51	            throw new ServiceException(422, "CAPACITY_EXCEEDED",
    52	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    53	        }
    54	        Quote quote = Quote.of(room, request.checkIn(), request.checkOut(), request.ratePlan());
    55	        Reservation draft = new Reservation(0, room.number(), request.guestName(), request.guestEmail(),
    56	                request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(), request.ratePlan(),
    57	                quote.nights(), quote.subtotal(), quote.discount(), quote.total(), ReservationStatus.PENDING,
    58	                Money.ZERO, null);
    59	        return transact(c -> {
    60	            reservations.lockRoom(c, room.number());
    61	            if (reservations.isRoomTaken(c, room.number(), request.checkIn(), request.checkOut())) {
    62	                throw new ServiceException(409, "ROOM_UNAVAILABLE",
    63	                        "O quarto " + room.number() + " já está reservado em alguma dessas noites");
    64	            }
    65	            return reservations.insert(c, draft);
    66	        });
    67	    }
    68	
    69	    public Reservation get(long id) {
    70	        return transact(c -> reservations.find(c, id).orElseThrow(() -> notFound(id)));
    71	    }
    72	
    73	    public Reservation confirm(long id) {
    74	        return change(id, (r, room) -> {
    75	            Reservation confirmed = r.confirm();
    76	            return new Outcome(confirmed, events.confirmed(confirmed, room));
    77	        });
    78	    }
    79	
    80	    public Reservation cancel(long id) {
    81	        return change(id, (r, room) -> {
    82	            Reservation cancelled = r.cancel();
    83	            List<Message> toSend = r.status() == ReservationStatus.CONFIRMED
    84	                    ? events.paidReservationCancelled(cancelled, room)
    85	                    : List.of();
    86	            return new Outcome(cancelled, toSend);
    87	        });
    88	    }
    89	
    90	    public Reservation checkIn(long id) {
    91	        return change(id, (r, room) -> new Outcome(r.checkInDone(), List.of()));
    92	    }
    93	
    94	    public Receipt checkOut(long id) {
    95	        Reservation done = change(id, (r, room) -> new Outcome(r.checkOutDone(), List.of()));
    96	        return Receipt.of(done, RoomCatalog.find(done.roomNumber()).orElseThrow());
    97	    }
    98	
    99	    /** Segunda via do comprovante; só existe para reserva paga. */
   100	    public Receipt receipt(long id) {
   101	        Reservation r = get(id);
   102	        if (!r.status().isPaid()) {
   103	            throw notAllowed("Reserva " + id + " está " + r.status() + " e não tem comprovante");
   104	        }
   105	        return Receipt.of(r, RoomCatalog.find(r.roomNumber()).orElseThrow());
   106	    }
   107	
   108	    public List<Message> sentMessages() {
   109	        return transact(messages::findAll);
   110	    }
   111	
   112	    private Reservation change(long id, Change change) {
   113	        return transact(c -> {
   114	            Reservation current = reservations.findForUpdate(c, id).orElseThrow(() -> notFound(id));
   115	            Room room = RoomCatalog.find(current.roomNumber()).orElseThrow();
   116	            Outcome outcome;
   117	            try {
   118	                outcome = change.apply(current, room);
   119	            } catch (NotAllowedException e) {
   120	                throw notAllowed(e.getMessage());
   121	            }
   122	            reservations.update(c, outcome.reservation());
   123	            messages.saveAll(c, outcome.messages());
   124	            return outcome.reservation();
   125	        });
   126	    }
   127	
   128	    private <T> T transact(Database.Work<T> body) {
   129	        try {
   130	            return database.inTransaction(body);
   131	        } catch (SQLException e) {
   132	            throw new IllegalStateException("Erro no banco de dados", e);
   133	        }
   134	    }
   135	
   136	    private static ServiceException notFound(long id) {
   137	        return new ServiceException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe");
   138	    }
   139	
   140	    private static ServiceException notAllowed(String message) {
   141	        return new ServiceException(409, "OPERATION_NOT_ALLOWED", message);
   142	    }
   143	}
