     1	package br.com.marealta.pousada.persistence;
     2	
     3	import java.sql.Connection;
     4	import java.sql.DriverManager;
     5	import java.sql.SQLException;
     6	import java.sql.Statement;
     7	
     8	public class Database {
     9	
    10	    public interface Work<T> {
    11	        T run(Connection connection) throws SQLException;
    12	    }
    13	
    14	    private final String url;
    15	    private final String user;
    16	    private final String password;
    17	
    18	    public Database(String url, String user, String password) {
    19	        this.url = url;
    20	        this.user = user;
    21	        this.password = password;
    22	    }
    23	
    24	    /** Cria o que o sistema precisa; espera o banco aceitar conexões se ele ainda estiver subindo. */
    25	    public void initialize() {
    26	        SQLException last = null;
    27	        for (int attempt = 1; attempt <= 30; attempt++) {
    28	            try {
    29	                inTransaction(c -> {
    30	                    try (Statement st = c.createStatement()) {
    31	                        st.execute("""
    32	                                CREATE TABLE IF NOT EXISTS reservations (
    33	                                    id BIGSERIAL PRIMARY KEY,
    34	                                    room_number INT NOT NULL,
    35	                                    guest_name TEXT NOT NULL,
    36	                                    guest_email TEXT NOT NULL,
    37	                                    guest_cpf TEXT NOT NULL,
    38	                                    check_in DATE NOT NULL,
    39	                                    check_out DATE NOT NULL,
    40	                                    guests INT NOT NULL,
    41	                                    rate_plan TEXT NOT NULL,
    42	                                    nights INT NOT NULL,
    43	                                    subtotal NUMERIC(12,2) NOT NULL,
    44	                                    discount NUMERIC(12,2) NOT NULL,
    45	                                    total NUMERIC(12,2) NOT NULL,
    46	                                    status TEXT NOT NULL,
    47	                                    amount_paid NUMERIC(12,2) NOT NULL,
    48	                                    refund NUMERIC(12,2)
    49	                                )""");
    50	                        st.execute("""
    51	                                CREATE TABLE IF NOT EXISTS messages (
    52	                                    id BIGSERIAL PRIMARY KEY,
    53	                                    channel TEXT NOT NULL,
    54	                                    recipient TEXT NOT NULL,
    55	                                    subject TEXT NOT NULL,
    56	                                    body TEXT NOT NULL
    57	                                )""");
    58	                    }
    59	                    return null;
    60	                });
    61	                return;
    62	            } catch (SQLException e) {
    63	                last = e;
    64	                try {
    65	                    Thread.sleep(1000);
    66	                } catch (InterruptedException ie) {
    67	                    Thread.currentThread().interrupt();
    68	                    break;
    69	                }
    70	            }
    71	        }
    72	        throw new IllegalStateException("Não foi possível preparar o banco de dados", last);
    73	    }
    74	
    75	    public <T> T inTransaction(Work<T> work) throws SQLException {
    76	        try (Connection connection = DriverManager.getConnection(url, user, password)) {
    77	            connection.setAutoCommit(false);
    78	            try {
    79	                T result = work.run(connection);
    80	                connection.commit();
    81	                return result;
    82	            } catch (Throwable t) {
    83	                connection.rollback();
    84	                throw t;
    85	            }
    86	        }
    87	    }
    88	}
