     6	
     7	/** Alta temporada: de 15/12 ao fim de fevereiro e todo julho. */
     8	public final class Season {
     9	
    10	    private static final BigDecimal HIGH_MULTIPLIER = new BigDecimal("1.20");
    11	
    12	    private Season() {
    13	    }
    14	
    15	    public static boolean isHigh(LocalDate night) {
    16	        Month month = night.getMonth();
    17	        return month == Month.JANUARY
    18	                || month == Month.FEBRUARY
    19	                || month == Month.JULY
    20	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    21	    }
    22	
    23	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    24	        BigDecimal rate = room.nightlyRate();
    25	        return Money.round(isHigh(night) ? rate.multiply(HIGH_MULTIPLIER) : rate);
    26	    }
