     6	public record Reservation(
     7	        long id,
     8	        int roomNumber,
     9	        String guestName,
    10	        String guestEmail,
    11	        String guestCpf,
    12	        LocalDate checkIn,
    13	        LocalDate checkOut,
    14	        int guests,
    15	        RatePlan ratePlan,
    16	        int nights,
    17	        BigDecimal subtotal,
    18	        BigDecimal discount,
    19	        BigDecimal total,
    20	        ReservationStatus status,
    21	        BigDecimal amountPaid,
    22	        BigDecimal refund) {
    23	
    24	    public Reservation confirm() {
    25	        return move(ReservationStatus.CONFIRMED, total, null);
    26	    }
    27	
    28	    public Reservation checkInDone() {
    29	        return move(ReservationStatus.CHECKED_IN, amountPaid, null);
    30	    }
    31	
    32	    public Reservation checkOutDone() {
    33	        return move(ReservationStatus.CHECKED_OUT, amountPaid, null);
    34	    }
    35	
    36	    public Reservation cancel() {
    37	        return move(ReservationStatus.CANCELLED, amountPaid, ratePlan.refund(amountPaid));
    38	    }
    39	
    40	    private Reservation move(ReservationStatus next, BigDecimal paid, BigDecimal refund) {
    41	        if (!status.canMoveTo(next)) {
    42	            throw new NotAllowedException("Reserva " + id + " está " + status + " e não pode ir para " + next);
    43	        }
    44	        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    45	                ratePlan, nights, subtotal, discount, total, next, paid, refund);
    46	    }
    47	
    48	    /** Dinheiro que ficou com a pousada: pago menos devolvido. */
    49	    public BigDecimal retained() {
    50	        return refund == null ? amountPaid : Money.round(amountPaid.subtract(refund));
    51	    }
    52	}
