    11	    public boolean canMoveTo(ReservationStatus next) {
    12	        return switch (next) {
    13	            case PENDING -> false;
    14	            case CONFIRMED -> this == PENDING;
    15	            case CHECKED_IN -> this == CONFIRMED;
    16	            case CHECKED_OUT -> this == CHECKED_IN;
    17	            case CANCELLED -> this == PENDING || this == CONFIRMED;
    18	        };
