  1	package br.com.marealta.pousada;
  2	
  3	import br.com.marealta.pousada.persistence.Database;
  4	import com.fasterxml.jackson.databind.JsonNode;
  5	import com.fasterxml.jackson.databind.ObjectMapper;
  6	import io.javalin.Javalin;
  7	import org.junit.jupiter.api.AfterAll;
  8	import org.junit.jupiter.api.BeforeAll;
  9	import org.junit.jupiter.api.Test;
 10	
 11	import java.net.URI;
 12	import java.net.http.HttpClient;
 13	import java.net.http.HttpRequest;
 14	import java.net.http.HttpResponse;
 15	import java.sql.Connection;
 16	import java.sql.DriverManager;
 17	import java.sql.Statement;
 18	import java.util.UUID;
 19	
 20	import static org.junit.jupiter.api.Assertions.*;
 21	import static org.junit.jupiter.api.Assumptions.assumeTrue;
 22	
 23	/** Roda contra o PostgreSQL de DB_URL, num schema próprio; é pulado se DB_URL não existir. */
 24	class ApiIntegrationTest {
 25	
 26	    static final ObjectMapper JSON = new ObjectMapper()
 27	            .enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)
 28	            .setNodeFactory(com.fasterxml.jackson.databind.node.JsonNodeFactory.withExactBigDecimals(true));
 29	    static final HttpClient HTTP = HttpClient.newHttpClient();
 30	    static Javalin app;
 31	    static String base;
 32	    static String schema;
 33	    static String url;
 34	
 35	    @BeforeAll
 36	    static void start() throws Exception {
 37	        String dbUrl = System.getenv("DB_URL");
 38	        assumeTrue(dbUrl != null && !dbUrl.isBlank(), "DB_URL não definido");
 39	        schema = "test_" + UUID.randomUUID().toString().replace("-", "");
 40	        try (Connection c = DriverManager.getConnection(dbUrl, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 41	             Statement st = c.createStatement()) {
 42	            st.execute("CREATE SCHEMA " + schema);
 43	        }
 44	        url = dbUrl + (dbUrl.contains("?") ? "&" : "?") + "currentSchema=" + schema;
 45	        Database db = new Database(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 46	        db.initialize();
 47	        app = Main.start(db, 0);
 48	        base = "http://localhost:" + app.port();
 49	    }
 50	
 51	    @AfterAll
 52	    static void stop() throws Exception {
 53	        if (app != null) {
 54	            app.stop();
 55	            try (Connection c = DriverManager.getConnection(System.getenv("DB_URL"), System.getenv("DB_USER"),
 56	                    System.getenv("DB_PASSWORD")); Statement st = c.createStatement()) {
 57	                st.execute("DROP SCHEMA " + schema + " CASCADE");
 58	            }
 59	        }
 60	    }
 61	
 62	    static HttpResponse<String> call(String method, String path, String body) throws Exception {
 63	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
 64	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 65	        return HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString());
 66	    }
 67	
 68	    static String booking(int room, String in, String out, int guests, String plan) {
